contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint preDeposit) public payable {
        require(address(this).balance >= preDeposit + 10);
        require(preDeposit % 10 == 0);
        // Build up a nonzero pot with deterministic-size steps
        while (preDeposit > 0) {
            c.play{value: 10}();
            preDeposit -= 10;
            if (c.pot() == 0) break;
        }
        uint potBefore = c.pot();
        uint balBefore = address(c).balance;
        bool reverted;
        try c.play{value: 10}() { reverted = false; } catch { reverted = true; }
        uint potAfter = c.pot();
        uint balAfter = address(c).balance;
        assert(reverted || (potAfter == potBefore + 10) ||
               (potAfter == 0 && balBefore >= potAfter && balAfter <= balBefore && potBefore + balAfter <= balBefore + 0));
    }
    receive() external payable {}
}

